def diff(x,y,p=''):
 if type(x)!=type(y):return [p]
 if isinstance(x,dict):return [z for k in sorted(set(x)|set(y)) for z in diff(x.get(k),y.get(k),p+'/'+k)]
 if isinstance(x,list):return [p] if len(x)!=len(y) else [z for i,(a,b) in enumerate(zip(x,y)) for z in diff(a,b,p+'/'+str(i))]
 return [] if x==y else [p]
